[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            navy: '#1B1464',
            'navy-light': '#2A1F8A',
            'navy-dark': '#0F0B3E',
            yellow: '#FFD930',
            'yellow-hover': '#F5CC00',
            teal: '#00C9A7',
            'teal-hover': '#00B396',
            gray: {
              50: '#F9FAFB',
              100: '#F3F4F6',
              200: '#E5E7EB',
              300: '#D1D5DB',
              400: '#9CA3AF',
              500: '#6B7280',
              600: '#4B5563',
              700: '#374151',
              800: '#1F2937',
              900: '#111827',
            }
          },
          fontFamily: {
            sans: ['Inter', 'system-ui', '-apple-system', 'sans-serif'],
          },
        }
      }
    }
  </script>
  <style>
    /* Base */
    *, *::before, *::after { box-sizing: border-box; }
    body { font-family: 'Inter', system-ui, -apple-system, sans-serif; }

    /* Animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }
    @keyframes slideDown {
      from { opacity: 0; transform: translateY(-8px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes pulse-soft {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(1.05); }
    }
    @keyframes float {
      0%, 100% { transform: translateY(0px); }
      50% { transform: translateY(-10px); }
    }
    .animate-fade-in-up { animation: fadeInUp 0.6s ease-out forwards; }
    .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
    .animate-slide-down { animation: slideDown 0.25s ease-out forwards; }
    .animate-float { animation: float 6s ease-in-out infinite; }
    .delay-100 { animation-delay: 0.1s; }
    .delay-200 { animation-delay: 0.2s; }
    .delay-300 { animation-delay: 0.3s; }
    .delay-400 { animation-delay: 0.4s; }
    .delay-500 { animation-delay: 0.5s; }
    .delay-600 { animation-delay: 0.6s; }

    /* Scroll reveal */
    .reveal { opacity: 0; transform: translateY(24px); transition: all 0.7s ease-out; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    /* Search autocomplete */
    .autocomplete-dropdown { display: none; }
    .autocomplete-dropdown.active { display: block; }

    /* Mobile menu */
    .mobile-menu { transform: translateX(100%); transition: transform 0.3s ease-out; }
    .mobile-menu.open { transform: translateX(0); }
    .mobile-overlay { opacity: 0; pointer-events: none; transition: opacity 0.3s ease; }
    .mobile-overlay.open { opacity: 1; pointer-events: auto; }

    /* Specialty card hover */
    .specialty-card { transition: all 0.3s ease; }
    .specialty-card:hover { transform: translateY(-6px); box-shadow: 0 20px 40px rgba(27, 20, 100, 0.12); }
    .specialty-card:hover .specialty-icon { transform: scale(1.1); }
    .specialty-icon { transition: transform 0.3s ease; }

    /* Stat counter animation */
    .stat-value { font-variant-numeric: tabular-nums; }

    /* Testimonial cards */
    .testimonial-card { transition: all 0.3s ease; }
    .testimonial-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(27, 20, 100, 0.1); }

    /* Step connector line */
    .step-connector { position: relative; }
    .step-connector::after {
      content: '';
      position: absolute;
      top: 28px;
      left: calc(50% + 36px);
      width: calc(100% - 72px);
      height: 2px;
      background: linear-gradient(90deg, #FFD930, #E5E7EB);
    }
    @media (max-width: 768px) {
      .step-connector::after { display: none; }
    }

    /* Phone mockup */
    .phone-mockup {
      background: linear-gradient(145deg, #1B1464 0%, #2A1F8A 100%);
      border-radius: 32px;
      padding: 8px;
      box-shadow: 0 40px 80px rgba(27, 20, 100, 0.25), 0 0 0 1px rgba(255,255,255,0.1) inset;
    }
    .phone-screen {
      border-radius: 26px;
      overflow: hidden;
    }

    /* Custom scrollbar */
    ::-webkit-scrollbar { width: 8px; }
    ::-webkit-scrollbar-track { background: #F3F4F6; }
    ::-webkit-scrollbar-thumb { background: #D1D5DB; border-radius: 4px; }
    ::-webkit-scrollbar-thumb:hover { background: #9CA3AF; }

    /* Hero gradient background */
    .hero-bg {
      background: linear-gradient(165deg, #1B1464 0%, #2A1F8A 40%, #3B2DA0 70%, #1B1464 100%);
      position: relative;
      overflow: hidden;
    }
    .hero-bg::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 80%;
      height: 200%;
      background: radial-gradient(ellipse, rgba(255, 217, 48, 0.08) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-bg::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 120px;
      background: linear-gradient(to top, #FFFFFF, transparent);
      pointer-events: none;
    }

    /* Subtle pattern on stats section */
    .stats-bg {
      background-color: #F9FAFB;
      background-image: radial-gradient(circle at 1px 1px, rgba(27, 20, 100, 0.03) 1px, transparent 0);
      background-size: 32px 32px;
    }
  </style>
</head>

<body class="bg-white text-gray-800 antialiased">

  <!-- ==================== HEADER ==================== -->
  <header id="header" class="fixed top-0 left-0 right-0 z-50 transition-all duration-300">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex items-center justify-between h-16 lg:h-20">
        <!-- Logo -->
        <a href="index.html" class="flex items-center gap-2 group" aria-label="MedBook Home">
          <div class="w-9 h-9 bg-yellow rounded-lg flex items-center justify-center group-hover:scale-105 transition-transform">
            <svg class="w-5 h-5 text-navy" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M4.26 10.147a60.438 60.438 0 0 0-.491 6.347A48.62 48.62 0 0 1 12 20.904a48.62 48.62 0 0 1 8.232-4.41 60.46 60.46 0 0 0-.491-6.347m-15.482 0a50.636 50.636 0 0 0-2.658-.813A59.906 59.906 0 0 1 12 3.493a59.903 59.903 0 0 1 10.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.717 50.717 0 0 1 12 13.489a50.702 50.702 0 0 1 7.74-3.342" />
            </svg>
          </div>
          <span class="text-xl font-bold header-logo-text text-white">MedBook</span>
        </a>

        <!-- Desktop Nav -->
        <nav class="hidden lg:flex items-center gap-1">
          <a href="#specialties" class="px-4 py-2 text-sm font-medium header-nav-link text-white/80 hover:text-white rounded-lg hover:bg-white/10 transition-all">Browse</a>
          <a href="#how-it-works" class="px-4 py-2 text-sm font-medium header-nav-link text-white/80 hover:text-white rounded-lg hover:bg-white/10 transition-all">Help</a>
          <a href="#" class="px-4 py-2 text-sm font-medium header-nav-link text-white/80 hover:text-white rounded-lg hover:bg-white/10 transition-all">Log In</a>
          <a href="#" class="ml-2 px-5 py-2.5 text-sm font-semibold bg-yellow text-navy rounded-xl hover:bg-yellow-hover transition-colors shadow-sm">Sign Up</a>
        </nav>

        <!-- Mobile Hamburger -->
        <button id="mobile-menu-btn" class="lg:hidden p-2 rounded-lg header-hamburger text-white hover:bg-white/10 transition-colors" aria-label="Open menu" aria-expanded="false">
          <svg class="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
            <path stroke-linecap="round" stroke-linejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
          </svg>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile Menu Overlay -->
  <div id="mobile-overlay" class="mobile-overlay fixed inset-0 z-50 bg-black/50 lg:hidden"></div>

  <!-- Mobile Menu Drawer -->
  <div id="mobile-menu" class="mobile-menu fixed top-0 right-0 bottom-0 w-72 z-50 bg-white shadow-2xl lg:hidden">
    <div class="flex items-center justify-between p-5 border-b border-gray-100">
      <span class="text-lg font-bold text-navy">Menu</span>
      <button id="mobile-menu-close" class="p-2 rounded-lg hover:bg-gray-100 transition-colors" aria-label="Close menu">
        <svg class="w-5 h-5 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
          <path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </div>
    <nav class="p-5 space-y-1">
      <a href="#specialties" class="mobile-nav-link block px-4 py-3 text-base font-medium text-gray-700 hover:bg-gray-50 rounded-xl transition-colors">Browse</a>
      <a href="#how-it-works" class="mobile-nav-link block px-4 py-3 text-base font-medium text-gray-700 hover:bg-gray-50 rounded-xl transition-colors">Help</a>
      <a href="#" class="block px-4 py-3 text-base font-medium text-gray-700 hover:bg-gray-50 rounded-xl transition-colors">Log In</a>
