    <div class="p-5 border-t border-gray-100 space-y-3">
      <a href="#" class="block w-full text-center px-5 py-3 text-sm font-semibold bg-yellow text-navy rounded-xl hover:bg-yellow-hover transition-colors">Sign Up</a>
    </div>
  </div>

  <!-- ==================== HERO ==================== -->
  <section class="hero-bg pt-28 pb-36 lg:pt-36 lg:pb-44">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
      <div class="text-center max-w-3xl mx-auto">
        <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold text-white leading-tight animate-fade-in-up">
          Find and book the care you need
        </h1>
        <p class="mt-5 text-lg sm:text-xl text-white/75 leading-relaxed animate-fade-in-up delay-200" style="opacity:0">
          Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.
        </p>
      </div>

      <!-- Search Bar -->
      <div class="mt-10 max-w-4xl mx-auto animate-fade-in-up delay-400" style="opacity:0">
        <div class="bg-white rounded-2xl shadow-2xl shadow-navy/20 p-2 sm:p-3">
          <form id="search-form" class="flex flex-col sm:flex-row gap-2 sm:gap-3" autocomplete="off">
            <!-- Specialty/Condition/Doctor -->
            <div class="relative flex-1 min-w-0">
              <div class="flex items-center gap-2 px-4 py-3 bg-gray-50 rounded-xl focus-within:bg-white focus-within:ring-2 focus-within:ring-navy/20 transition-all">
                <svg class="w-5 h-5 text-gray-400 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                  <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z" />
                </svg>
                <input id="search-specialty" type="text" placeholder="Search by condition, specialty, or doctor name" class="w-full bg-transparent text-sm text-gray-800 placeholder-gray-400 outline-none" aria-label="Search by condition, specialty, or doctor name" />
              </div>
              <!-- Autocomplete dropdown -->
              <div id="autocomplete-dropdown" class="autocomplete-dropdown absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-xl border border-gray-100 overflow-hidden z-50">
                <div class="py-2">
                  <div class="px-4 py-1.5 text-xs font-semibold text-gray-400 uppercase tracking-wide">Suggestions</div>
                </div>
              </div>
            </div>

            <!-- Location -->
            <div class="relative sm:w-52 min-w-0">
              <div class="flex items-center gap-2 px-4 py-3 bg-gray-50 rounded-xl focus-within:bg-white focus-within:ring-2 focus-within:ring-navy/20 transition-all">
                <svg class="w-5 h-5 text-gray-400 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                  <path stroke-linecap="round" stroke-linejoin="round" d="M15 10.5a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z" />
                  <path stroke-linecap="round" stroke-linejoin="round" d="M19.5 10.5c0 7.142-7.5 11.25-7.5 11.25S4.5 17.642 4.5 10.5a7.5 7.5 0 1 1 15 0Z" />
                </svg>
                <input id="search-location" type="text" placeholder="City, state, or zip" class="w-full bg-transparent text-sm text-gray-800 placeholder-gray-400 outline-none" aria-label="City, state, or zip code" />
