                  <button type="button" class="insurance-option w-full text-left px-4 py-2.5 text-sm text-gray-700 hover:bg-navy/5 transition-colors" data-value="blue-cross">Blue Cross Blue Shield</button>
                  <button type="button" class="insurance-option w-full text-left px-4 py-2.5 text-sm text-gray-700 hover:bg-navy/5 transition-colors" data-value="cigna">Cigna</button>
                  <button type="button" class="insurance-option w-full text-left px-4 py-2.5 text-sm text-gray-700 hover:bg-navy/5 transition-colors" data-value="united">UnitedHealthcare</button>
                  <button type="button" class="insurance-option w-full text-left px-4 py-2.5 text-sm text-gray-700 hover:bg-navy/5 transition-colors" data-value="humana">Humana</button>
