  <!-- ==================== SPECIALTIES ==================== -->
  <section id="specialties" class="py-20 lg:py-28 bg-white">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="text-center mb-14 reveal">
        <h2 class="text-3xl sm:text-4xl font-bold text-navy">Popular specialties</h2>
        <p class="mt-3 text-lg text-gray-500 max-w-xl mx-auto">Find the right provider for your needs. Browse top specialties or search for a specific condition.</p>
      </div>

      <div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4 lg:gap-5">
        <!-- Primary Care -->
        <a href="#" class="specialty-card group bg-white border border-gray-100 rounded-2xl p-6 text-center hover:border-yellow/50 shadow-sm reveal">
