            <svg class="w-7 h-7 text-navy" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z" />
            </svg>
          </div>
          <h3 class="font-semibold text-gray-800 text-sm">Primary Care</h3>
          <p class="mt-1 text-xs text-gray-400 leading-snug">Checkups & preventive care</p>
        </a>

        <!-- Dentist -->
        <a href="#" class="specialty-card group bg-white border border-gray-100 rounded-2xl p-6 text-center hover:border-yellow/50 shadow-sm reveal">
          <div class="specialty-icon w-14 h-14 mx-auto bg-cyan-50 rounded-2xl flex items-center justify-center mb-4">
            <svg class="w-7 h-7 text-cyan-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M12 2C9.5 2 8 3.5 8 5c0 2 1 3 2 5 .4.8.6 2.5.8 4 .3 2.5.5 5 1.2 5s.9-2.5 1.2-5c.2-1.5.4-3.2.8-4 1-2 2-3 2-5 0-1.5-1.5-3-4-3z" />
            </svg>
          </div>
          <h3 class="font-semibold text-gray-800 text-sm">Dentist</h3>
          <p class="mt-1 text-xs text-gray-400 leading-snug">Cleanings & oral health</p>
        </a>

        <!-- Dermatologist -->
        <a href="#" class="specialty-card group bg-white border border-gray-100 rounded-2xl p-6 text-center hover:border-yellow/50 shadow-sm reveal">
          <div class="specialty-icon w-14 h-14 mx-auto bg-rose-50 rounded-2xl flex items-center justify-center mb-4">
            <svg class="w-7 h-7 text-rose-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M9.75 3.104v5.714a2.25 2.25 0 0 1-.659 1.591L5 14.5M9.75 3.104c-.251.023-.501.05-.75.082m.75-.082a24.301 24.301 0 0 1 4.5 0m0 0v5.714c0 .597.237 1.17.659 1.591L19.8 15.3M14.25 3.104c.251.023.501.05.75.082M19.8 15.3l-1.57.393A9.065 9.065 0 0 1 12 15a9.065 9.065 0 0 0-6.23.693L5 14.5m14.8.8 1.402 1.402c1.232 1.232.65 3.318-1.067 3.611A48.309 48.309 0 0 1 12 21c-2.773 0-5.491-.235-8.135-.687-1.718-.293-2.3-2.379-1.067-3.61L5 14.5" />
            </svg>
          </div>
          <h3 class="font-semibold text-gray-800 text-sm">Dermatologist</h3>
          <p class="mt-1 text-xs text-gray-400 leading-snug">Skin conditions & acne</p>
        </a>

        <!-- Psychiatrist -->
        <a href="#" class="specialty-card group bg-white border border-gray-100 rounded-2xl p-6 text-center hover:border-yellow/50 shadow-sm reveal">
          <div class="specialty-icon w-14 h-14 mx-auto bg-purple-50 rounded-2xl flex items-center justify-center mb-4">
            <svg class="w-7 h-7 text-purple-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M12 18v-5.25m0 0a6.01 6.01 0 0 0 1.5-.189m-1.5.189a6.01 6.01 0 0 1-1.5-.189m3.75 7.478a12.06 12.06 0 0 1-4.5 0m3.75 2.383a14.406 14.406 0 0 1-3 0M14.25 18v-.192c0-.983.658-1.823 1.508-2.316a7.5 7.5 0 1 0-7.517 0c.85.493 1.509 1.333 1.509 2.316V18" />
            </svg>
          </div>
          <h3 class="font-semibold text-gray-800 text-sm">Psychiatrist</h3>
          <p class="mt-1 text-xs text-gray-400 leading-snug">Mental health & medication</p>
        </a>

