  <script>
    // ===== Header scroll behavior =====
    const header = document.getElementById('header');
    let lastScrollY = 0;

    function updateHeader() {
      const scrollY = window.scrollY;
      const heroHeight = document.querySelector('.hero-bg').offsetHeight;

      if (scrollY > 50) {
        header.classList.add('bg-white', 'shadow-sm', 'border-b', 'border-gray-100');
        header.classList.remove('bg-transparent');
        // Update text colors for white header
        header.querySelectorAll('.header-logo-text').forEach(el => {
          el.classList.remove('text-white');
          el.classList.add('text-navy');
        });
        header.querySelectorAll('.header-nav-link').forEach(el => {
          el.classList.remove('text-white/80', 'hover:text-white', 'hover:bg-white/10');
          el.classList.add('text-gray-600', 'hover:text-navy', 'hover:bg-navy/5');
        });
        header.querySelectorAll('.header-hamburger').forEach(el => {
          el.classList.remove('text-white', 'hover:bg-white/10');
          el.classList.add('text-gray-600', 'hover:bg-gray-100');
        });
      } else {
        header.classList.remove('bg-white', 'shadow-sm', 'border-b', 'border-gray-100');
        header.classList.add('bg-transparent');
        header.querySelectorAll('.header-logo-text').forEach(el => {
          el.classList.add('text-white');
          el.classList.remove('text-navy');
        });
        header.querySelectorAll('.header-nav-link').forEach(el => {
          el.classList.add('text-white/80', 'hover:text-white', 'hover:bg-white/10');
          el.classList.remove('text-gray-600', 'hover:text-navy', 'hover:bg-navy/5');
        });
        header.querySelectorAll('.header-hamburger').forEach(el => {
          el.classList.add('text-white', 'hover:bg-white/10');
          el.classList.remove('text-gray-600', 'hover:bg-gray-100');
        });
      }
      lastScrollY = scrollY;
    }

    window.addEventListener('scroll', updateHeader, { passive: true });
    updateHeader();

    // ===== Mobile menu =====
    const mobileMenuBtn = document.getElementById('mobile-menu-btn');
    const mobileMenuClose = document.getElementById('mobile-menu-close');
    const mobileMenu = document.getElementById('mobile-menu');
    const mobileOverlay = document.getElementById('mobile-overlay');

    function openMobileMenu() {
      mobileMenu.classList.add('open');
      mobileOverlay.classList.add('open');
      mobileMenuBtn.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }

    function closeMobileMenu() {
      mobileMenu.classList.remove('open');
      mobileOverlay.classList.remove('open');
      mobileMenuBtn.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    mobileMenuBtn.addEventListener('click', openMobileMenu);
    mobileMenuClose.addEventListener('click', closeMobileMenu);
    mobileOverlay.addEventListener('click', closeMobileMenu);

    // Close mobile menu on nav link click
    document.querySelectorAll('.mobile-nav-link').forEach(link => {
      link.addEventListener('click', closeMobileMenu);
    });

    // ===== Search autocomplete =====
    const searchInput = document.getElementById('search-specialty');
    const autocompleteDropdown = document.getElementById('autocomplete-dropdown');
    const suggestions = [
      { text: 'Dentist', sub: 'Specialty' },
      { text: 'Dermatologist', sub: 'Specialty' },
      { text: 'Primary Care', sub: 'Specialty' },
      { text: 'Psychiatrist', sub: 'Specialty' },
      { text: 'Eye Doctor', sub: 'Specialty' },
      { text: 'Orthopedic Surgeon', sub: 'Specialty' },
      { text: 'Back pain', sub: 'Condition' },
      { text: 'Skin rash', sub: 'Condition' },
      { text: 'Anxiety', sub: 'Condition' },
      { text: 'Headache', sub: 'Condition' },
      { text: 'Dr. Sarah Chen', sub: 'Doctor' },
      { text: 'Dr. Mark Rivera', sub: 'Doctor' },
      { text: 'Dr. Emily Park', sub: 'Doctor' },
    ];

    searchInput.addEventListener('input', function() {
      const query = this.value.trim().toLowerCase();
      if (query.length === 0) {
        autocompleteDropdown.classList.remove('active');
        return;
      }

      const matches = suggestions.filter(s =>
        s.text.toLowerCase().includes(query)
      ).slice(0, 6);

      if (matches.length === 0) {
        autocompleteDropdown.classList.remove('active');
        return;
      }

      let html = '<div class="py-1.5"><div class="px-4 py-1 text-xs font-semibold text-gray-400 uppercase tracking-wide">Suggestions</div>';
      matches.forEach(m => {
        const iconColor = m.sub === 'Specialty' ? 'text-navy' : m.sub === 'Condition' ? 'text-teal' : 'text-yellow';
        html += `
          <button type="button" class="suggestion-item w-full flex items-center gap-3 px-4 py-2.5 hover:bg-navy/5 transition-colors text-left" data-value="${m.text}">
            <svg class="w-4 h-4 ${iconColor} shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
              <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z" />
            </svg>
            <span class="text-sm text-gray-700">${m.text}</span>
            <span class="ml-auto text-xs text-gray-400">${m.sub}</span>
          </button>`;
      });
      html += '</div>';
      autocompleteDropdown.innerHTML = html;
      autocompleteDropdown.classList.add('active');

      // Suggestion click handler
      autocompleteDropdown.querySelectorAll('.suggestion-item').forEach(item => {
        item.addEventListener('click', function() {
          searchInput.value = this.dataset.value;
          autocompleteDropdown.classList.remove('active');
        });
      });
    });

    searchInput.addEventListener('focus', function() {
      if (this.value.trim().length > 0) {
        this.dispatchEvent(new Event('input'));
      }
    });

    // Close dropdown on outside click
    document.addEventListener('click', function(e) {
      if (!e.target.closest('#search-specialty') && !e.target.closest('#autocomplete-dropdown')) {
        autocompleteDropdown.classList.remove('active');
      }
    });

    // ===== Insurance dropdown =====
    const insuranceTrigger = document.getElementById('insurance-select-trigger');
    const insuranceDropdown = document.getElementById('insurance-dropdown');
    const insuranceLabel = document.getElementById('insurance-label');

    insuranceTrigger.addEventListener('click', function(e) {
      e.stopPropagation();
      insuranceDropdown.classList.toggle('active');
    });

    document.querySelectorAll('.insurance-option').forEach(option => {
      option.addEventListener('click', function(e) {
        e.stopPropagation();
        const value = this.dataset.value;
        insuranceLabel.textContent = value ? this.textContent.trim() : 'Insurance plan';
        insuranceLabel.classList.toggle('text-gray-400', !value);
        insuranceLabel.classList.toggle('text-gray-700', !!value);
        insuranceDropdown.classList.remove('active');
      });
    });

    document.addEventListener('click', function(e) {
      if (!e.target.closest('#insurance-select-trigger') && !e.target.closest('#insurance-dropdown')) {
        insuranceDropdown.classList.remove('active');
      }
    });

    // ===== Search form submit =====
    document.getElementById('search-form').addEventListener('submit', function(e) {
      e.preventDefault();
      const specialty = searchInput.value.trim();
      const location = document.getElementById('search-location').value.trim();
      // In a real app, this would navigate to search results
      // For now, show a brief visual feedback
      const btn = this.querySelector('button[type="submit"]');
      const originalText = btn.textContent;
      btn.textContent = 'Searching...';
      btn.disabled = true;
      setTimeout(() => {
        btn.textContent = originalText;
        btn.disabled = false;
      }, 1500);
    });

    // ===== Geolocation =====
    document.getElementById('geolocate-btn').addEventListener('click', function() {
      const locationInput = document.getElementById('search-location');
      if ('geolocation' in navigator) {
        locationInput.value = 'Detecting location...';
        navigator.geolocation.getCurrentPosition(
          (pos) => {
            locationInput.value = `${pos.coords.latitude.toFixed(2)}, ${pos.coords.longitude.toFixed(2)}`;
          },
          () => {
            locationInput.value = '';
            locationInput.placeholder = 'Location unavailable';
          }
        );
      }
    });

    // ===== Scroll reveal =====
    const revealElements = document.querySelectorAll('.reveal');
    const revealObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

    revealElements.forEach(el => revealObserver.observe(el));

    // ===== Stats counter animation =====
    const statValues = document.querySelectorAll('.stat-value');
    const statsObserver = new IntersectionObserver((entries) => {
